const Ext = ({ href, color, icon, children }) => (
    <a href={href} target="_blank" rel="noopener noreferrer">
        <Tag color={color} style={{ marginLeft: 10 }}>
            {icon} {children}
        </Tag>
    </a>
)

const PopoverImages = ({ images }) => (
    <div>
        {images.map((src, i) => (
            <img
                key={i}
                width="280"
                src={src.src ?? src}
                alt={src.alt ?? 'preview'}
                loading="lazy"
            />
        ))}
    </div>
)

const ViewTag = ({ color, content, label = 'view' }) => (
    <Popover content={content} title={false}>
        <Tag color={color} style={{ marginLeft: 10 }}>
            <FileSearchOutlined /> {label}
        </Tag>
    </Popover>
)

